package com.gameaggregator.billingservice.domain;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;import java.util.UUID;@Entity @Table(name="invoices") public class Invoice{@Id public UUID id=UUID.randomUUID();@Column(nullable=false,unique=true)public String invoiceNumber;@Column(nullable=false)public UUID clientId;@Column(nullable=false)public LocalDate cycleFrom;@Column(nullable=false)public LocalDate cycleTo;@Column(nullable=false,precision=19,scale=6)public BigDecimal total;@Column(nullable=false)public String currency;@Column(nullable=false)public String paymentStatus="UNPAID";@Column(nullable=false)public Instant createdAt=Instant.now();protected Invoice(){}public Invoice(String n,UUID c,LocalDate f,LocalDate t,BigDecimal a,String u){invoiceNumber=n;clientId=c;cycleFrom=f;cycleTo=t;total=a;currency=u;}}